    typealias SwiftType = MmFfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> MmFfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Config(
            try FfiConverterString.read(from: &buf)
            )
        case 2: return .Io(
            try FfiConverterString.read(from: &buf)
            )
        case 3: return .Metadata(
            try FfiConverterString.read(from: &buf)
            )
        case 4: return .Rename(
            try FfiConverterString.read(from: &buf)
            )
        case 5: return .RuleEngine(
            try FfiConverterString.read(from: &buf)
            )
        case 6: return .Watcher(
            try FfiConverterString.read(from: &buf)
            )
        case 7: return .Unknown(
            try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: MmFfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Config(v1):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .Io(v1):
            writeInt(&buf, Int32(2))
